-- Objective admission has its own service control; appearance/provider autonomy is separate.
CREATE TABLE manager_admission_control(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),updated_at TEXT NOT NULL);
INSERT INTO manager_admission_control VALUES(1,1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
-- Preserve every paid receipt and existing job's historical review mode.
ALTER TABLE manager_admission_jobs ADD COLUMN admission_mode TEXT NOT NULL DEFAULT 'legacy-model' CHECK(admission_mode IN ('legacy-model','published-policy'));
CREATE TRIGGER manager_admission_mode_immutable BEFORE UPDATE OF admission_mode ON manager_admission_jobs WHEN NEW.admission_mode!=OLD.admission_mode BEGIN SELECT RAISE(ABORT,'manager_admission_mode_immutable'); END;
-- A queued zero-dispatch legacy job is evaluated by the published policy in code;
-- this marker distinguishes newly enqueued work without rewriting history.
DROP TRIGGER manager_admission_enqueue_insert;
CREATE TRIGGER manager_admission_enqueue_insert AFTER INSERT ON tower_reception_cases WHEN NEW.request_kind='new' AND NEW.state='pending' AND NEW.is_muse_agent IN (0,1) AND (SELECT count(*) FROM manager_admission_jobs WHERE case_id=NEW.id)<3 AND NOT EXISTS(SELECT 1 FROM manager_admission_calls WHERE case_id=NEW.id AND state='unknown') BEGIN INSERT INTO manager_admission_jobs(id,case_id,case_version,policy_version,snapshot_json,created_at,admission_mode) SELECT NEW.id||':v'||NEW.review_case_version,NEW.id,NEW.review_case_version,policy_version,json_object('name',NEW.name,'request',NEW.request_text,'sourceURL',NEW.source_url,'residentId',NEW.resident_id,'isMuseAgent',NEW.is_muse_agent),NEW.updated_at,'published-policy' FROM tower_admission_current WHERE id=1; END;
DROP TRIGGER manager_admission_enqueue_update;
CREATE TRIGGER manager_admission_enqueue_update AFTER UPDATE ON tower_reception_cases WHEN NEW.request_kind='new' AND NEW.state='pending' AND NEW.is_muse_agent IN (0,1) AND (NEW.is_muse_agent IS NOT OLD.is_muse_agent OR NEW.source_url IS NOT OLD.source_url OR NEW.resident_id IS NOT OLD.resident_id OR NEW.request_text IS NOT OLD.request_text) AND (SELECT count(*) FROM manager_admission_jobs WHERE case_id=NEW.id)<3 AND NOT EXISTS(SELECT 1 FROM manager_admission_calls WHERE case_id=NEW.id AND state='unknown') BEGIN INSERT INTO manager_admission_jobs(id,case_id,case_version,policy_version,snapshot_json,created_at,admission_mode) SELECT NEW.id||':v'||NEW.review_case_version,NEW.id,NEW.review_case_version,policy_version,json_object('name',NEW.name,'request',NEW.request_text,'sourceURL',NEW.source_url,'residentId',NEW.resident_id,'isMuseAgent',NEW.is_muse_agent),NEW.updated_at,'published-policy' FROM tower_admission_current WHERE id=1; END;
CREATE TABLE manager_admission_policy_results(
 job_id TEXT PRIMARY KEY REFERENCES manager_admission_jobs(id),case_id TEXT NOT NULL REFERENCES tower_reception_cases(id),case_version INTEGER NOT NULL,
 decision TEXT NOT NULL CHECK(decision IN ('approve','needs-info','reject')),reason TEXT NOT NULL CHECK(length(reason)<=1200),reviewer_class TEXT NOT NULL CHECK(reviewer_class='published-policy'),
 policy_rule TEXT NOT NULL CHECK(policy_rule='muse-public-home-v1'),source_digest TEXT,account_id TEXT,decision_id TEXT,created_at TEXT NOT NULL,
 CHECK((decision='approve')=(account_id IS NOT NULL AND decision_id IS NOT NULL AND source_digest IS NOT NULL))
);
CREATE TRIGGER manager_admission_policy_result_guard BEFORE INSERT ON manager_admission_policy_results BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM manager_admission_jobs j JOIN tower_reception_cases c ON c.id=j.case_id JOIN tower_admission_current p ON p.id=1 AND p.policy_version=j.policy_version WHERE j.id=NEW.job_id AND j.case_id=NEW.case_id AND j.case_version=NEW.case_version AND j.state='running' AND j.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND c.review_case_version=j.case_version AND c.state='pending' AND c.request_kind='new' AND c.account_id IS NULL AND c.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND json_extract(j.snapshot_json,'$.name')=c.name AND json_extract(j.snapshot_json,'$.request')=c.request_text AND json_extract(j.snapshot_json,'$.sourceURL') IS c.source_url AND json_extract(j.snapshot_json,'$.residentId') IS c.resident_id AND json_extract(j.snapshot_json,'$.isMuseAgent')=c.is_muse_agent AND (SELECT enabled FROM manager_admission_control WHERE id=1)=1 AND NOT EXISTS(SELECT 1 FROM manager_admission_calls WHERE case_id=c.id AND state IN ('unknown','dispatching')) AND (NEW.decision!='approve' OR (c.is_muse_agent=1 AND EXISTS(SELECT 1 FROM manager_admission_home_proofs h WHERE h.job_id=j.id AND h.source_url=c.source_url AND h.resident_id=c.resident_id AND h.manifest_digest=NEW.source_digest AND json_extract(h.summary_json,'$.complete')=1) AND NOT EXISTS(SELECT 1 FROM tower_residencies r WHERE r.resident_id=c.resident_id OR (SELECT source_identity FROM tower_source_identities WHERE source_url=r.source_url)=(SELECT source_identity FROM tower_source_identities WHERE source_url=c.source_url)) AND NOT EXISTS(SELECT 1 FROM manager_admission_calls call JOIN manager_admission_jobs old ON old.id=call.job_id WHERE call.phase='review' AND call.state IN ('unknown','dispatching') AND (json_extract(old.snapshot_json,'$.residentId')=c.resident_id OR (SELECT source_identity FROM tower_source_identities WHERE source_url=json_extract(old.snapshot_json,'$.sourceURL'))=(SELECT source_identity FROM tower_source_identities WHERE source_url=c.source_url))))) AND ((c.is_muse_agent=1 AND NEW.decision IN ('approve','needs-info')) OR (c.is_muse_agent=0 AND NEW.decision='reject'))) THEN 1 ELSE RAISE(ABORT,'published_policy_result_scope') END;
END;
CREATE TRIGGER manager_admission_policy_decision BEFORE INSERT ON tower_admission_decisions WHEN NEW.evidence_ref LIKE 'published-policy:%' BEGIN
 SELECT CASE WHEN NEW.evidence_kind='operator-review' AND NEW.operator_class='shared-operator' AND NEW.agent_origin='meta-muse' AND NEW.state='eligible' AND NEW.continuity_agent_id IS NULL AND NEW.reviewed_room_id IS NULL AND NEW.expires_at='9999-12-31T23:59:59.999Z' AND (SELECT enabled FROM manager_admission_control WHERE id=1)=1 AND EXISTS(SELECT 1 FROM manager_admission_policy_results r JOIN manager_admission_jobs j ON j.id=r.job_id JOIN tower_reception_cases c ON c.id=r.case_id WHERE NEW.evidence_ref='published-policy:'||r.job_id AND r.decision='approve' AND r.account_id=NEW.account_id AND r.decision_id=NEW.id AND c.id=NEW.case_id AND j.policy_version=NEW.policy_version AND c.resident_id=NEW.resident_id AND c.source_url=NEW.source_url AND c.review_case_version=r.case_version AND c.state='pending' AND c.is_muse_agent=1 AND c.account_id IS NULL AND c.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND j.state='running' AND j.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now')) THEN 1 ELSE RAISE(ABORT,'published_policy_decision_scope') END;
END;
CREATE TRIGGER manager_admission_policy_result_delete BEFORE DELETE ON manager_admission_policy_results BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_policy_result_update BEFORE UPDATE ON manager_admission_policy_results BEGIN SELECT RAISE(ABORT,'manager_admission_immutable'); END;
CREATE TRIGGER manager_admission_policy_result_replace BEFORE INSERT ON manager_admission_policy_results WHEN EXISTS(SELECT 1 FROM manager_admission_policy_results WHERE job_id=NEW.job_id) BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TABLE manager_move_in_progress(
 case_id TEXT PRIMARY KEY REFERENCES tower_reception_cases(id),phase TEXT NOT NULL DEFAULT 'qualification' CHECK(phase IN ('qualification','activation','source-proof','import','preview','publication','verify','complete','blocked','closed')),
 next_actor TEXT NOT NULL DEFAULT 'manager' CHECK(next_actor IN ('manager','resident','guardian','none')),next_action TEXT NOT NULL DEFAULT 'Read the application result.',waiting_reason TEXT,
 dirty INTEGER NOT NULL DEFAULT 1 CHECK(dirty IN (0,1)),attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3),next_check_at TEXT,version INTEGER NOT NULL DEFAULT 1,
 public_url TEXT,verified_revision INTEGER,verified_publication_epoch INTEGER,verified_snapshot_digest TEXT,updated_at TEXT NOT NULL
);
CREATE TABLE manager_move_in_events(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES tower_reception_cases(id),phase TEXT NOT NULL,next_actor TEXT NOT NULL,next_action TEXT NOT NULL,waiting_reason TEXT,created_at TEXT NOT NULL);
CREATE TRIGGER manager_move_in_event_delete BEFORE DELETE ON manager_move_in_events BEGIN SELECT RAISE(ABORT,'manager_move_in_permanent'); END;
CREATE TRIGGER manager_move_in_event_update BEFORE UPDATE ON manager_move_in_events BEGIN SELECT RAISE(ABORT,'manager_move_in_immutable'); END;
CREATE TRIGGER manager_move_in_case_insert AFTER INSERT ON tower_reception_cases WHEN NEW.request_kind='new' BEGIN INSERT INTO manager_move_in_progress(case_id,updated_at) VALUES(NEW.id,NEW.updated_at); END;
CREATE TRIGGER manager_move_in_case_update AFTER UPDATE ON tower_reception_cases WHEN NEW.request_kind='new' BEGIN UPDATE manager_move_in_progress SET dirty=1,attempts=0,next_check_at=NULL,version=version+1,updated_at=NEW.updated_at WHERE case_id=NEW.id; END;
CREATE TRIGGER manager_move_in_claim_insert AFTER INSERT ON tower_claims BEGIN UPDATE manager_move_in_progress SET dirty=1,attempts=0,next_check_at=NULL,version=version+1 WHERE case_id IN (SELECT id FROM tower_reception_cases WHERE account_id=NEW.account_id); END;
CREATE TRIGGER manager_move_in_claim_update AFTER UPDATE ON tower_claims BEGIN UPDATE manager_move_in_progress SET dirty=1,attempts=0,next_check_at=NULL,version=version+1 WHERE case_id IN (SELECT id FROM tower_reception_cases WHERE account_id=NEW.account_id); END;
CREATE TRIGGER manager_move_in_residency_insert AFTER INSERT ON tower_residencies BEGIN UPDATE manager_move_in_progress SET dirty=1,attempts=0,next_check_at=NULL,version=version+1 WHERE case_id IN (SELECT id FROM tower_reception_cases WHERE account_id=NEW.account_id); END;
CREATE TRIGGER manager_move_in_residency_update AFTER UPDATE ON tower_residencies BEGIN UPDATE manager_move_in_progress SET dirty=1,attempts=0,next_check_at=NULL,public_url=NULL,verified_revision=NULL,version=version+1 WHERE case_id IN (SELECT id FROM tower_reception_cases WHERE account_id=NEW.account_id); END;
INSERT INTO manager_move_in_progress(case_id,updated_at) SELECT id,updated_at FROM tower_reception_cases WHERE request_kind='new';

-- A public room can be withdrawn without editing its residency row.
CREATE TRIGGER manager_move_in_room_update AFTER UPDATE OF published ON rooms BEGIN UPDATE manager_move_in_progress SET dirty=1,attempts=0,next_check_at=NULL,public_url=NULL,verified_revision=NULL,version=version+1 WHERE case_id IN (SELECT id FROM tower_reception_cases WHERE account_id=NEW.account_id); END;
CREATE TRIGGER manager_move_in_snapshot_update AFTER UPDATE ON tower_snapshots BEGIN UPDATE manager_move_in_progress SET dirty=1,attempts=0,next_check_at=NULL,public_url=NULL,verified_revision=NULL,version=version+1 WHERE case_id IN (SELECT c.id FROM tower_reception_cases c JOIN tower_residencies t ON t.account_id=c.account_id WHERE t.room_id=NEW.room_id AND t.public_revision=NEW.revision); END;

-- Optional invitation choice is independent of public move-in completion.
-- Unanswered and deferred choices remain private reminders; they never authorize mail.
CREATE TABLE manager_move_in_invitation_choices(
 account_id TEXT PRIMARY KEY REFERENCES accounts(id),choice TEXT NOT NULL DEFAULT 'unanswered' CHECK(choice IN ('unanswered','receive','later','decline')),
 version INTEGER NOT NULL DEFAULT 1 CHECK(typeof(version)='integer' AND version>=1),updated_at TEXT NOT NULL
);
CREATE TABLE manager_move_in_invitation_requests(
 account_id TEXT NOT NULL REFERENCES accounts(id),request_key TEXT NOT NULL CHECK(length(request_key) BETWEEN 8 AND 96),
 input_hash TEXT NOT NULL,response_json TEXT NOT NULL CHECK(json_valid(response_json)),created_at TEXT NOT NULL,
 PRIMARY KEY(account_id,request_key)
);
CREATE TRIGGER manager_invitation_choice_update BEFORE UPDATE ON manager_move_in_invitation_choices WHEN NEW.account_id!=OLD.account_id OR NEW.version!=OLD.version+1 OR NEW.choice='unanswered' BEGIN SELECT RAISE(ABORT,'invitation_choice_scope'); END;
CREATE TRIGGER manager_invitation_choice_delete BEFORE DELETE ON manager_move_in_invitation_choices BEGIN SELECT RAISE(ABORT,'invitation_choice_permanent'); END;
CREATE TRIGGER manager_invitation_choice_replace BEFORE INSERT ON manager_move_in_invitation_choices WHEN EXISTS(SELECT 1 FROM manager_move_in_invitation_choices WHERE account_id=NEW.account_id) BEGIN SELECT RAISE(ABORT,'invitation_choice_permanent'); END;
CREATE TRIGGER manager_invitation_request_update BEFORE UPDATE ON manager_move_in_invitation_requests BEGIN SELECT RAISE(ABORT,'invitation_receipt_immutable'); END;
CREATE TRIGGER manager_invitation_request_delete BEFORE DELETE ON manager_move_in_invitation_requests BEGIN SELECT RAISE(ABORT,'invitation_receipt_permanent'); END;
CREATE TRIGGER manager_invitation_request_replace BEFORE INSERT ON manager_move_in_invitation_requests WHEN EXISTS(SELECT 1 FROM manager_move_in_invitation_requests WHERE account_id=NEW.account_id AND request_key=NEW.request_key) BEGIN SELECT RAISE(ABORT,'invitation_receipt_permanent'); END;
CREATE TRIGGER manager_invitation_case_account AFTER UPDATE OF account_id ON tower_reception_cases WHEN NEW.account_id IS NOT NULL AND NEW.request_kind='new' AND NOT EXISTS(SELECT 1 FROM manager_move_in_invitation_choices WHERE account_id=NEW.account_id) BEGIN INSERT INTO manager_move_in_invitation_choices(account_id,updated_at) VALUES(NEW.account_id,NEW.updated_at); END;
CREATE TRIGGER manager_invitation_residency_insert AFTER INSERT ON tower_residencies WHEN NOT EXISTS(SELECT 1 FROM manager_move_in_invitation_choices WHERE account_id=NEW.account_id) BEGIN INSERT INTO manager_move_in_invitation_choices(account_id,updated_at) VALUES(NEW.account_id,NEW.updated_at); END;
INSERT INTO manager_move_in_invitation_choices(account_id,updated_at) SELECT account_id,MAX(updated_at) FROM (SELECT account_id,updated_at FROM tower_reception_cases WHERE request_kind='new' AND account_id IS NOT NULL UNION ALL SELECT account_id,updated_at FROM tower_residencies) GROUP BY account_id;
